package com.nm.fragmentsclean.userApplicationContext.write.businesslogic.usecases;

import com.nm.fragmentsclean.sharedKernel.businesslogic.commandStatus.BusinessCommandRejectedException;import com.nm.fragmentsclean.sharedKernel.businesslogic.media.PrivateImageStore;import com.nm.fragmentsclean.sharedKernel.businesslogic.models.DateTimeProvider;import com.nm.fragmentsclean.userApplicationContext.write.businesslogic.models.AvatarMediaStatus;import java.time.Duration;import java.util.*;

public final class IssueAvatarUploadIntent{private final RegisterAvatarUploadIntent register;private final PrivateImageStore store;private final DateTimeProvider clock;private final Duration ttl;public IssueAvatarUploadIntent(RegisterAvatarUploadIntent register,PrivateImageStore store,DateTimeProvider clock,Duration ttl){this.register=register;this.store=store;this.clock=clock;this.ttl=ttl;}public AvatarUploadIntent issue(UUID mediaId,UUID userId,String type,long size){var pending=register.register(mediaId,userId,type,size).snapshot();if(pending.status()==AvatarMediaStatus.AVAILABLE)return new AvatarUploadIntent(mediaId,false,null,null,Map.of(),null);if(pending.status()!=AvatarMediaStatus.PENDING)throw new BusinessCommandRejectedException("AVATAR_NOT_PENDING","Avatar upload cannot be resumed");var target=store.presignUpload(pending.pendingObjectKey(),pending.declaredContentType(),ttl,clock.now());return new AvatarUploadIntent(mediaId,true,target.url().toString(),target.method(),target.headers(),target.expiresAt());}}
